contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // to send Ether to c.go, require this test contract has at least `amount`
        require(address(this).balance >= amount, "insufficient balance to forward");

        // observe owner and c balance before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = address(c).balance;

        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceAfter = address(c).balance;

        // General property: either the call reverted, or owner unchanged and C drained to zero
        assert(reverted || (ownerAfter == ownerBefore && balanceAfter == 0));
    }

    // accept incoming Ether if C forwards to us in some executions
    receive() external payable {}
}

